import pandas as pd, numpy as np
# summarize DRC dose vs retention across all intervene datasets
for e in ['experiment_4_csv','experiment_5_csv','experiment_6_csv','experiment_8_csv','experiment_11_csv','experiment_1_csv']:
    try:
        df=pd.read_csv(eval(e))
        cols=df.columns.tolist()
        drc = df['do_DryRoomControl'].dropna().unique() if 'do_DryRoomControl' in cols else 'na'
        print(e, 'DRC levels:', drc, 'meanRet=%.2f'%df['CapacityRetention'].mean())
    except Exception as ex:
        print(e,'err',ex)
